def avg(xs):
    return sum(xs) / len(xs)


def median(xs):
    """Return the median of xs; for even lengths, the mean of the two middle values."""
    if not xs:
        raise ValueError("median() arg is an empty sequence")
    s = sorted(xs)
    mid = len(s) // 2
    if len(s) % 2:
        return s[mid]
    return (s[mid - 1] + s[mid]) / 2

